1/* Import Fonts */
2@import url("https://fonts.googleapis.com/css2?family=Euclid+Circular+A:wght@400;500&display=swap");
3@import url("https://fonts.googleapis.com/css2?family=Galdeano&display=swap");
4
5/* Reset browser defaults */
6* {
7    padding: 0;
8    margin: 0;
9    box-sizing: border-box;
10    font-family: 'Euclid Circular A', sans-serif;
11}
12
13/* Contain image */
14img {
15    max-width: 100%;
16    height: auto;
17}
18
19/* Style header and footer */
20.header,
21.footer {
22    background-color: #2c2e48;
23    color: white;
24    min-height: 50px;
25    display: flex;
26    justify-content: center;
27    align-items: center;
28}
29
30/* Style sections */
31.main>section {
32    display: flex;
33    flex-direction: column;
34    align-items: center;
35    justify-content: center;
36    min-height: 300px;
37    padding: 80px;
38    gap: 32px;
39}
40
41/* Alternate section background colors */
42.main section:nth-child(odd) {
43    background-color: #c6b6d7;
44}
45
46.main section:nth-child(even) {
47    background-color: #efefef;
48}
